import 'package:flutter/material.dart';
import '../../core/api_client.dart';
import '../../core/theme.dart';
import '../auth/session_controller.dart';

class NotificationsScreen extends StatefulWidget { const NotificationsScreen({super.key,required this.session}); final SessionController session; @override State<NotificationsScreen> createState()=>_NotificationsScreenState(); }
class _NotificationsScreenState extends State<NotificationsScreen>{bool loading=true;List<dynamic> items=[];String? error;@override void initState(){super.initState();load();}Future<void> load()async{setState(()=>loading=true);try{final data=await widget.session.notifications();if(mounted)setState(()=>items=data['notifications'] as List<dynamic>? ?? []);}on ApiException catch(e){if(mounted)setState(()=>error=e.message);}finally{if(mounted)setState(()=>loading=false);}}Future<void> markAll()async{final old=items;setState(()=>items=items.map((e)=>{...(e as Map<String,dynamic>),'read_at':'now'}).toList());try{await widget.session.markNotificationsRead();}on ApiException catch(e){if(mounted){setState(()=>items=old);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}}}@override Widget build(BuildContext context)=>Scaffold(backgroundColor:const Color(0xFFF5F8FC),appBar:AppBar(backgroundColor:const Color(0xFFF5F8FC),title:const Text('Notifications',style:TextStyle(color:Color(0xFF0F2440),fontWeight:FontWeight.w800)),actions:[TextButton(onPressed:markAll,child:const Text('Mark all read'))]),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[if(loading)const Padding(padding:EdgeInsets.all(50),child:Center(child:CircularProgressIndicator()))else if(error!=null)Text(error!)else if(items.isEmpty)const Padding(padding:EdgeInsets.all(50),child:Center(child:Text('No notifications')))else ...[const Text('Today',style:TextStyle(fontWeight:FontWeight.w800,fontSize:18)),const SizedBox(height:10),for(final item in items)_Notice(item:item as Map<String,dynamic>)]])));}
class _Notice extends StatelessWidget{const _Notice({required this.item});final Map<String,dynamic> item;@override Widget build(BuildContext context){final unread=item['read_at']==null;return Card(color:unread?const Color(0xFFF0F6FF):Colors.white,child:ListTile(leading:Container(width:42,height:42,decoration:BoxDecoration(color:HRMateTheme.blue.withValues(alpha:.12),borderRadius:BorderRadius.circular(12)),child:const Icon(Icons.notifications_rounded,color:HRMateTheme.blue)),title:Text(item['title']?.toString()??'',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(item['body']?.toString()??''),trailing:unread?const CircleAvatar(radius:4,backgroundColor:HRMateTheme.blue):null));}}
